/* Website settings › Performance (round V): how fast each published website is for its visitors. `site_rum_events`, one row per measured page view (the site, the time, the page path with ids taken out, the kind of page, phone or computer, the browser family, the country the edge reported, the connection type and up to six numbers; nothing about the visitor), kept 30 days. `site_rum_counters`, every page view that arrived per site and UTC day, which decides the sampling (all up to 1000 a day, then one in ten, then one in a hundred, each kept row with its weight) and marks a day rolled up. `site_rum_daily`, per site, day, device and one of page, page type, browser or country, a histogram per metric, kept 13 months. `site_lab_tests`, the latest Google PageSpeed Insights result per site and strategy. A creator reads only their own sites (row level security); only the server writes. Functions: `record_site_rum` (the write), `site_rum_window` (a window of days summed, as the asker), `site_rum_replace_day` (the rollup, a day replaced whole), `site_rum_cleanup` (retention). Run after `06`. No existing row changes. Until it runs, visitors' measurements are dropped and the Performance tab says it is not set up yet. Safe to run again. */
create table if not exists public.site_rum_events ( id bigint generated always as identity primary key, install_id uuid not null references public.store_theme_installs(id) on delete cascade, creator_id uuid not null references public.creators(id) on delete cascade, at timestamptz not null default now(), path text not null check (char_length(path) between 1 and 160 and left(path, 1) = '/'), page_type text not null check (page_type in ('home', 'product', 'collection', 'page', 'policy', 'blog', 'search', 'cart', 'account', 'checkout', 'other')), device text not null check (device in ('mobile', 'desktop')), browser text not null check (char_length(browser) between 1 and 24), country text check (country ~ '^[A-Z]{2}$'), conn text check (conn in ('slow-2g', '2g', '3g', '4g')), kind text not null default 'load' check (kind in ('load', 'soft')), lcp_ms integer check (lcp_ms between 0 and 60000), inp_ms integer check (inp_ms between 0 and 60000), cls real check (cls between 0 and 10), fcp_ms integer check (fcp_ms between 0 and 60000), ttfb_ms integer check (ttfb_ms between 0 and 60000), nav_ms integer check (nav_ms between 0 and 60000), weight real not null default 1 check (weight >= 1 and weight <= 1000) );
create index if not exists site_rum_events_install_at on public.site_rum_events (install_id, at);
create index if not exists site_rum_events_at on public.site_rum_events (at);
create table if not exists public.site_rum_counters ( install_id uuid not null references public.store_theme_installs(id) on delete cascade, day date not null, creator_id uuid not null references public.creators(id) on delete cascade, seen integer not null default 0, rolled_at timestamptz, primary key (install_id, day) );
create table if not exists public.site_rum_daily ( install_id uuid not null references public.store_theme_installs(id) on delete cascade, creator_id uuid not null references public.creators(id) on delete cascade, day date not null, device text not null check (device in ('mobile', 'desktop')), dim text not null check (dim in ('all', 'path', 'type', 'browser', 'country')), key text not null default '' check (char_length(key) <= 160), views real not null default 0, samples integer not null default 0, lcp_h real[] not null default '{}', lcp_n integer not null default 0, inp_h real[] not null default '{}', inp_n integer not null default 0, cls_h real[] not null default '{}', cls_n integer not null default 0, fcp_h real[] not null default '{}', fcp_n integer not null default 0, ttfb_h real[] not null default '{}', ttfb_n integer not null default 0, nav_h real[] not null default '{}', nav_n integer not null default 0, primary key (install_id, day, device, dim, key) );
create index if not exists site_rum_daily_install_dim_day on public.site_rum_daily (install_id, dim, day);
create table if not exists public.site_lab_tests ( install_id uuid not null references public.store_theme_installs(id) on delete cascade, creator_id uuid not null references public.creators(id) on delete cascade, strategy text not null check (strategy in ('mobile', 'desktop')), url text not null check (char_length(url) <= 600), ran_at timestamptz not null default now(), result jsonb not null, primary key (install_id, strategy) );
alter table public.site_rum_events enable row level security;
alter table public.site_rum_counters enable row level security;
alter table public.site_rum_daily enable row level security;
alter table public.site_lab_tests enable row level security;
drop policy if exists "creators read their own site page views" on public.site_rum_events;
create policy "creators read their own site page views" on public.site_rum_events for select to authenticated using (creator_id in (select c.id from public.creators c where c.user_id = auth.uid()));
drop policy if exists "creators read their own site page view counts" on public.site_rum_counters;
create policy "creators read their own site page view counts" on public.site_rum_counters for select to authenticated using (creator_id in (select c.id from public.creators c where c.user_id = auth.uid()));
drop policy if exists "creators read their own site speed by day" on public.site_rum_daily;
create policy "creators read their own site speed by day" on public.site_rum_daily for select to authenticated using (creator_id in (select c.id from public.creators c where c.user_id = auth.uid()));
drop policy if exists "creators read their own lab tests" on public.site_lab_tests;
create policy "creators read their own lab tests" on public.site_lab_tests for select to authenticated using (creator_id in (select c.id from public.creators c where c.user_id = auth.uid()));
revoke insert, update, delete on public.site_rum_events, public.site_rum_counters, public.site_rum_daily, public.site_lab_tests from anon, authenticated;
revoke all on public.site_rum_events, public.site_rum_counters, public.site_rum_daily, public.site_lab_tests from anon;
grant select on public.site_rum_events, public.site_rum_counters, public.site_rum_daily, public.site_lab_tests to authenticated;
grant select, insert, update, delete on public.site_rum_events, public.site_rum_counters, public.site_rum_daily, public.site_lab_tests to service_role;
create or replace function public.record_site_rum(p_install uuid, p_creator uuid, p_path text, p_type text, p_device text, p_browser text, p_country text, p_conn text, p_kind text, p_lcp integer, p_inp integer, p_cls real, p_fcp integer, p_ttfb integer, p_nav integer, p_full integer default 1000, p_mid integer default 10000, p_mid_rate real default 0.1, p_far_rate real default 0.01) returns boolean language plpgsql security definer set search_path = public as $$ declare v_day date := (now() at time zone 'utc')::date; v_seen integer; v_rate real; begin if p_device not in ('mobile', 'desktop') then return false; end if; insert into public.site_rum_counters (install_id, day, creator_id, seen) values (p_install, v_day, p_creator, 1) on conflict (install_id, day) do update set seen = public.site_rum_counters.seen + 1, rolled_at = null returning seen into v_seen; v_rate := case when v_seen <= p_full then 1 when v_seen <= p_mid then greatest(p_mid_rate, 0.001) else greatest(p_far_rate, 0.001) end; if v_rate < 1 and random() >= v_rate then return false; end if; insert into public.site_rum_events (install_id, creator_id, path, page_type, device, browser, country, conn, kind, lcp_ms, inp_ms, cls, fcp_ms, ttfb_ms, nav_ms, weight) values (p_install, p_creator, p_path, p_type, p_device, p_browser, p_country, p_conn, p_kind, case when p_lcp between 0 and 60000 then p_lcp end, case when p_inp between 0 and 60000 then p_inp end, case when p_cls between 0 and 10 then p_cls end, case when p_fcp between 0 and 60000 then p_fcp end, case when p_ttfb between 0 and 60000 then p_ttfb end, case when p_nav between 0 and 60000 then p_nav end, 1.0 / v_rate); return true; end; $$;
revoke all on function public.record_site_rum(uuid, uuid, text, text, text, text, text, text, text, integer, integer, real, integer, integer, integer, integer, integer, real, real) from public, anon, authenticated;
grant execute on function public.record_site_rum(uuid, uuid, text, text, text, text, text, text, text, integer, integer, real, integer, integer, integer, integer, integer, real, real) to service_role;
create or replace function public.site_rum_hadd(a real[], b real[]) returns real[] language sql immutable parallel safe as $$ select case when a is null then b when b is null then a else array(select coalesce(a[i], 0) + coalesce(b[i], 0) from generate_series(1, greatest(cardinality(a), cardinality(b))) as i order by i) end $$;
create or replace aggregate public.site_rum_hsum(real[]) (sfunc = public.site_rum_hadd, stype = real[]);
create or replace function public.site_rum_window(p_install uuid, p_from date, p_to date) returns table (device text, dim text, key text, views double precision, samples bigint, lcp_h real[], lcp_n bigint, inp_h real[], inp_n bigint, cls_h real[], cls_n bigint, fcp_h real[], fcp_n bigint, ttfb_h real[], ttfb_n bigint, nav_h real[], nav_n bigint) language sql stable security invoker set search_path = public as $$ select d.device, d.dim, d.key, sum(d.views)::double precision, sum(d.samples)::bigint, public.site_rum_hsum(d.lcp_h), sum(d.lcp_n)::bigint, public.site_rum_hsum(d.inp_h), sum(d.inp_n)::bigint, public.site_rum_hsum(d.cls_h), sum(d.cls_n)::bigint, public.site_rum_hsum(d.fcp_h), sum(d.fcp_n)::bigint, public.site_rum_hsum(d.ttfb_h), sum(d.ttfb_n)::bigint, public.site_rum_hsum(d.nav_h), sum(d.nav_n)::bigint from public.site_rum_daily d where d.install_id = p_install and d.day between p_from and p_to group by d.device, d.dim, d.key $$;
revoke all on function public.site_rum_window(uuid, date, date) from public, anon;
grant execute on function public.site_rum_window(uuid, date, date) to authenticated, service_role;
create or replace function public.site_rum_replace_day(p_install uuid, p_day date, p_rows jsonb) returns integer language plpgsql security definer set search_path = public as $$ declare v_creator uuid; v_n integer; begin select i.creator_id into v_creator from public.store_theme_installs i where i.id = p_install; if v_creator is null or jsonb_typeof(p_rows) <> 'array' then return 0; end if; delete from public.site_rum_daily where install_id = p_install and day = p_day; insert into public.site_rum_daily (install_id, creator_id, day, device, dim, key, views, samples, lcp_h, lcp_n, inp_h, inp_n, cls_h, cls_n, fcp_h, fcp_n, ttfb_h, ttfb_n, nav_h, nav_n) select p_install, v_creator, p_day, r->>'device', r->>'dim', left(coalesce(r->>'key', ''), 160), coalesce((r->>'views')::real, 0), coalesce((r->>'samples')::integer, 0), array(select x::real from jsonb_array_elements_text(coalesce(r->'lcp_h', '[]')) with ordinality t(x, o) order by o), coalesce((r->>'lcp_n')::integer, 0), array(select x::real from jsonb_array_elements_text(coalesce(r->'inp_h', '[]')) with ordinality t(x, o) order by o), coalesce((r->>'inp_n')::integer, 0), array(select x::real from jsonb_array_elements_text(coalesce(r->'cls_h', '[]')) with ordinality t(x, o) order by o), coalesce((r->>'cls_n')::integer, 0), array(select x::real from jsonb_array_elements_text(coalesce(r->'fcp_h', '[]')) with ordinality t(x, o) order by o), coalesce((r->>'fcp_n')::integer, 0), array(select x::real from jsonb_array_elements_text(coalesce(r->'ttfb_h', '[]')) with ordinality t(x, o) order by o), coalesce((r->>'ttfb_n')::integer, 0), array(select x::real from jsonb_array_elements_text(coalesce(r->'nav_h', '[]')) with ordinality t(x, o) order by o), coalesce((r->>'nav_n')::integer, 0) from jsonb_array_elements(p_rows) r where r->>'device' in ('mobile', 'desktop') and r->>'dim' in ('all', 'path', 'type', 'browser', 'country') on conflict (install_id, day, device, dim, key) do nothing; get diagnostics v_n = row_count; update public.site_rum_counters set rolled_at = now() where install_id = p_install and day = p_day; return v_n; end; $$;
revoke all on function public.site_rum_replace_day(uuid, date, jsonb) from public, anon, authenticated;
grant execute on function public.site_rum_replace_day(uuid, date, jsonb) to service_role;
create or replace function public.site_rum_cleanup(p_raw_days integer default 30, p_rollup_days integer default 400) returns integer language plpgsql security definer set search_path = public as $$ declare v_today date := (now() at time zone 'utc')::date; v_n integer; v_total integer := 0; begin delete from public.site_rum_events e where e.at < ((v_today - p_raw_days)::timestamp at time zone 'utc') and (e.at < ((v_today - p_raw_days - 5)::timestamp at time zone 'utc') or exists (select 1 from public.site_rum_counters c where c.install_id = e.install_id and c.day = (e.at at time zone 'utc')::date and c.rolled_at is not null)); get diagnostics v_n = row_count; v_total := v_total + v_n; delete from public.site_rum_daily where day < v_today - p_rollup_days; get diagnostics v_n = row_count; v_total := v_total + v_n; delete from public.site_rum_counters where day < v_today - p_rollup_days; get diagnostics v_n = row_count; v_total := v_total + v_n; return v_total; end; $$;
revoke all on function public.site_rum_cleanup(integer, integer) from public, anon, authenticated;
grant execute on function public.site_rum_cleanup(integer, integer) to service_role;
notify pgrst, 'reload schema';
